-- =====================================================================
-- Mais frases para todos os momentos, com referências a momentos
-- icônicos do programa (sem nomes reais): o "fiel, traidor, não sei"
-- apontando para cada um, a "maior ovelha", o escudo escondido no bolso,
-- o "cem por cento fiel", o recado de despedida, o veneno na taça...
-- =====================================================================

INSERT INTO phrases (phase, tone, behavior_id, text)
