  ('ENDGAME', 'HUMOR', NULL, '{user} lembrou que ninguém ali sabe a senha do Wi-Fi até hoje. "Isso sim é traição."'),
  ('ENDGAME', 'HUMOR', 'Caótico', '{user} votou e depois perguntou em quem tinha votado.'),
  ('ENDGAME', 'HUMOR', 'Brincalhão', '{user} disse que se tiver traidor ali, ele(a) merece o prêmio só pelo cansaço.')
) AS v(phase, tone, behavior, text)
LEFT JOIN behaviors b ON lower(b.name) = lower(v.behavior)
ON CONFLICT DO NOTHING;
